import React, { useState } from 'react';
import './Career.css';

const Career = () => {
    // Set to true to show the vacancy, false to hide it
    const [hasVacancy] = useState(false); 

    // YOUR PORTAL URL HERE
    const portalUrl = "https://your-external-portal-link.com";

    return (
        <div className="career-page">
            {/* Hero Section provides consistent spacing from Navbar */}
            <div className="career-hero">
                <h1>Work With Infinity</h1>
                <p>Build your career in the microfinance sector of Nepal.</p>
            </div>

            <div className="career-container">
                {!hasVacancy ? (
                    <div className="no-vacancy animated">
                        <div className="icon">📢</div>
                        <h1>Current Vacancies</h1>
                        <p>There are no open positions at the moment. However, we are always looking for talented individuals. Please send your CV to <strong>hr@infinitylbsl.com.np</strong> for future consideration.</p>
                    </div>
                ) : (
                    <div className="vacancy-portal-card animated">
                        <div className="badge">We Are Hiring!</div>
                        <h2>Exciting Opportunities Await</h2>
                        <p>
                            We are looking for passionate individuals to join our growing team. 
                            Click the button below to view current openings and submit your 
                            application through our official recruitment portal.
                        </p>
                        
                        <div className="portal-action">
                            <a 
                                href={portalUrl} 
                                target="_blank" 
                                rel="noopener noreferrer" 
                                className="portal-button"
                            >
                                Apply via Online Portal
                            </a>
                        </div>
                        
                        <p className="alternative-text">
                            Having trouble? You can also mail your documents to <strong>info@infinitylbsl.com.np</strong>
                        </p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Career;
